// Generated by Claude Code
package ui;

import grading.common.Messages;
import grading.reporting.AttemptReportWriter;
import grading.reporting.ReportArchive;
import grading.session.GradingSession;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.util.Optional;
import java.util.function.BooleanSupplier;
import java.util.function.Consumer;
import java.util.function.Supplier;
import javafx.stage.Window;

/**
 * Saves copies of the latest run's reports where the marker chooses: one student's PDF report, or every
 * report as one ZIP file. The reports in the grading-reports folder are only copied, never changed.
 */
final class ReportSaving {

    private final Supplier<GradingSession> session;
    private final BooleanSupplier busy;
    private final BackgroundTasks tasks;
    private final Supplier<String> sheetStatus;
    private final Consumer<ActionResult> show;

    /**
     * @param session     the current session; replaced when the reports folder changes
     * @param busy        whether an import, save or grading run is going on
     * @param tasks       runs the ZIP save off the JavaFX thread
     * @param sheetStatus the score sheet text the Activity tab shows below the save result
     * @param show        shows the result of each save
     */
    ReportSaving(Supplier<GradingSession> session, BooleanSupplier busy, BackgroundTasks tasks,
            Supplier<String> sheetStatus, Consumer<ActionResult> show) {
        this.session = session;
        this.busy = busy;
        this.tasks = tasks;
        this.sheetStatus = sheetStatus;
        this.show = show;
    }

    /** Asks where to save the student's report, then saves a copy there. */
    void downloadStudentReport(String username, Window owner) {
        Optional<Path> report = reportOf(username);
        if (report.isEmpty()) {
            show.accept(ActionResult.status(noReport(username)));
            return;
        }
        String name = report.get().getFileName().toString();
        FileDialogs.save("Save " + username + "'s report", owner, "Reports", name.substring(name.lastIndexOf('.')),
                name, null).ifPresent(target -> saveStudentReport(username, target));
    }

    /** Saves a copy of the student's report from the latest run to {@code target}. */
    void saveStudentReport(String username, Path target) {
        Optional<Path> report = reportOf(username);
        if (report.isEmpty()) {
            show.accept(ActionResult.status(noReport(username)));
            return;
        }
        try {
            Files.copy(report.get(), target, StandardCopyOption.REPLACE_EXISTING);
            show.accept(ActionResult.status("Report saved to " + target.getFileName()));
        } catch (IOException failure) {
            show.accept(ActionResult.status("Report not saved: " + Messages.describe(failure)));
        }
    }

    /** Asks where to save the ZIP file of every report, then saves it there. */
    void downloadAllReports(Window owner) {
        if (session.get().reportsFolder().isEmpty()) {
            return;
        }
        FileDialogs.save("Save the grading reports", owner, "ZIP files", ".zip",
                "grading-reports-" + session.get().latestAttemptId() + ".zip", null).ifPresent(this::saveAllReports);
    }

    /** Saves the latest run's reports as one ZIP file, in the background. */
    void saveAllReports(Path zipFile) {
        Optional<Path> reports = session.get().reportsFolder();
        if (busy.getAsBoolean() || reports.isEmpty()) {
            return;
        }
        show.accept(ActionResult.status("Saving the reports"));
        tasks.run(() -> {
            ReportArchive.save(reports.get(), zipFile);
            return zipFile;
        }, "report-archive", saved -> showSaved("Reports saved", "Reports saved to " + saved.getFileName(),
                saved.toAbsolutePath().toString()),
                failure -> showSaved("Reports not saved", "Reports not saved", Messages.describe(failure)));
    }

    private void showSaved(String status, String shortStatus, String detail) {
        show.accept(new ActionResult(status + "\n" + detail + "\n\n" + sheetStatus.get(), status, shortStatus));
    }

    private Optional<Path> reportOf(String username) {
        return session.get().reportsFolder()
                .flatMap(folder -> AttemptReportWriter.studentReportOf(folder, username));
    }

    private static String noReport(String username) {
        return "No report was written for " + username;
    }
}
